  function renderTime(){const data=state.data,p=progress(),nTrain=54,history=data.slice(0,nTrain),future=data.slice(nTrain),actual=future.map(d=>d.y);if(state.step===0){if(state.view==='2d')renderPlot([{x:data.map(d=>d.t),y:data.map(d=>d.y),mode:'lines+markers',type:'scatter',name:'Observed series',line:{color:'#2563eb'}}],{xaxis:{...layout2d.xaxis,title:'Time'},yaxis:{...layout2d.yaxis,title:'Value'}});else render3D([{x:data.map(d=>d.t),y:data.map(d=>Math.sin(d.t/5.3)),z:data.map(d=>d.y),mode:'lines+markers',type:'scatter3d',name:'Observed series',marker:{size:2.5,color:'#2563eb'}}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'Time'},yaxis:{...scene3d.yaxis,title:'Seasonal phase'},zaxis:{...scene3d.zaxis,title:'Value'}}});practicalMetrics.innerHTML=metric('Model state','Not trained')+metric('History',nTrain)+metric('Horizon',future.length)+metric('Progress','0%');simNote.textContent='Reset state: only the observed time series is visible before fitting.';return}
    let forecast=[];
    if(cfg.slug==='prophet'){
      const t0=history[0].t,t1=history.at(-1).t,y0=mean(history.slice(0,8).map(d=>d.y)),y1=mean(history.slice(-8).map(d=>d.y)),slope=(y1-y0)/(t1-t0),seasonAmp=(.5+1.5*p),base=history.at(-1).y;forecast=future.map((d,i)=>base+p*slope*(i+1)+p*seasonAmp*Math.sin((d.t+1)/5.3));
    }else{
      const d=history.map((q,i)=>i? q.y-history[i-1].y:0),phi=.25+.55*p,last=history.at(-1).y,lastDiff=d.at(-1),seasonLag=12;forecast=future.map((q,i)=>{const seasonal=history[Math.max(0,nTrain-seasonLag+i%seasonLag)].y-history[Math.max(0,nTrain-2*seasonLag+i%seasonLag)].y;return last+(i+1)*phi*lastDiff+p*.45*seasonal});
    }
    const histTrace={x:history.map(d=>d.t),y:history.map(d=>d.y),mode:'lines+markers',type:'scatter',name:'Observed history',line:{color:'#2563eb'}},futureTrace={x:future.map(d=>d.t),y:actual,mode:'lines',type:'scatter',name:'Held-out future',line:{color:'#cbd5e1',dash:'dot'}},predTrace={x:future.map(d=>d.t),y:forecast,mode:'lines+markers',type:'scatter',name:cfg.slug==='prophet'?'Additive trend + seasonality':'ARIMA/SARIMA-style forecast',line:{color:'#f97316',width:3}};
    if(state.view==='2d')renderPlot([histTrace,futureTrace,predTrace],{xaxis:{...layout2d.xaxis,title:'Time'},yaxis:{...layout2d.yaxis,title:'Value'}});else render3D([{x:data.map(d=>d.t),y:data.map(d=>Math.sin(d.t/5.3)),z:data.map(d=>d.y),mode:'lines+markers',type:'scatter3d',name:'Observed seasonal trajectory',marker:{size:2.5,color:'#2563eb'}},{x:future.map(d=>d.t),y:future.map(d=>Math.sin(d.t/5.3)),z:forecast,mode:'lines+markers',type:'scatter3d',name:'Forecast trajectory',line:{color:'#f97316',width:6}}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'Time'},yaxis:{...scene3d.yaxis,title:'Seasonal phase'},zaxis:{...scene3d.zaxis,title:'Value'}}});const mae=mean(actual.map((v,i)=>Math.abs(v-forecast[i])));practicalMetrics.innerHTML=metric('Forecast MAE',mae.toFixed(2))+metric('Mechanism',cfg.slug==='prophet'?'Additive':'AR + seasonal')+metric('Horizon',forecast.length)+metric('Progress',`${Math.round(p*100)}%`);simNote.textContent=cfg.slug==='prophet'?'Prophet-style view separates an additive trend from recurring seasonal structure before extrapolating future values.':'ARIMA/SARIMA-style view predicts from recent changes and seasonal lag structure rather than generic exponential smoothing.';
  }
  function renderRepresentation(generative=false){const pts=state.data,p=progress(),mapped=pts.map(q=>{const cx=[-2,2,0][q.g],cy=[-1.5,1.5,2.3][q.g],cz=[-1.4,1.4,.3][q.g];if(generative){const a=Math.atan2(q.y,q.x),r=1.5+.3*Math.sin(3*a);return{x:(1-p)*q.x+p*r*Math.cos(a),y:(1-p)*q.y+p*r*Math.sin(a),z:(1-p)*q.z+p*.6*Math.sin(2*a),g:q.g}}return{x:(1-p)*q.x+p*(cx+.35*q.x),y:(1-p)*q.y+p*(cy+.35*q.y),z:(1-p)*q.z+p*(cz+.35*q.z),g:q.g}});if(state.view==='2d')renderPlot([0,1,2].map(k=>({x:mapped.filter(q=>q.g===k).map(q=>q.x),y:mapped.filter(q=>q.g===k).map(q=>q.y),mode:'markers',type:'scatter',name:generative?`Sample group ${k+1}`:`Latent group ${k+1}`,marker:{size:7,color:COLORS[k],opacity:.65}})),{xaxis:{...layout2d.xaxis,title:generative?'Generated coordinate 1':'Latent dimension 1'},yaxis:{...layout2d.yaxis,title:generative?'Generated coordinate 2':'Latent dimension 2'}});else render3D([0,1,2].map(k=>({x:mapped.filter(q=>q.g===k).map(q=>q.x),y:mapped.filter(q=>q.g===k).map(q=>q.y),z:mapped.filter(q=>q.g===k).map(q=>q.z),mode:'markers',type:'scatter3d',name:`Group ${k+1}`,marker:{size:3.8,color:COLORS[k],opacity:.65}})),{scene:{...scene3d,zaxis:{...scene3d.zaxis,title:generative?'Generated coordinate 3':'Latent dimension 3'}}});const centers=[0,1,2].map(k=>{const a=mapped.filter(q=>q.g===k);return[mean(a.map(q=>q.x)),mean(a.map(q=>q.y)),mean(a.map(q=>q.z))]}),sep=mean([[0,1],[0,2],[1,2]].map(([a,b])=>Math.hypot(centers[a][0]-centers[b][0],centers[a][1]-centers[b][1],centers[a][2]-centers[b][2])));simNote.textContent=generative?'Training/denoising transforms an initially noisy cloud toward a structured sample manifold.':'The representation becomes more structured as training advances; 3D exposes an additional latent dimension.';practicalMetrics.innerHTML=metric(generative?'Structure score':'Latent separation',sep.toFixed(2))+metric('Progress',`${Math.round(p*100)}%`)+metric('View',state.view.toUpperCase())+metric('Method',cfg.name)}
  function renderRL(){const p=progress(),n=9,val=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>p*(1-.08*(Math.abs(8-i)+Math.abs(8-j)))+.1*(1-p)*Math.sin(i+j))),xs=Array.from({length:n},(_,i)=>i),ys=[...xs],pathY=[0,1,1,2,3,4,5,7,8];if(state.view==='2d')renderPlot([{x:xs,y:ys,z:val,type:'heatmap',colorscale:'Blues',showscale:true,colorbar:{title:'V(s)'}},{x:xs,y:pathY,mode:'lines+markers',type:'scatter',name:'Greedy path',line:{color:'#f97316',width:4}}],{xaxis:{...layout2d.xaxis,title:'Grid x'},yaxis:{...layout2d.yaxis,title:'Grid y'}});else render3D([{x:xs,y:ys,z:val,type:'surface',colorscale:'Blues',showscale:false,name:'Value surface'},{x:xs,y:pathY,z:pathY.map((y,i)=>val[i][y]),mode:'lines+markers',type:'scatter3d',name:'Policy path',line:{color:'#f97316',width:7}}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'State x'},yaxis:{...scene3d.yaxis,title:'State y'},zaxis:{...scene3d.zaxis,title:'Estimated value'}}});practicalMetrics.innerHTML=metric('Mean learned value',mean(val.flat()).toFixed(2))+metric('Discount / planning',pretty(params.gamma||params.planning||params.beta||.9))+metric('Policy maturity',`${Math.round(p*100)}%`)+metric('View',state.view.toUpperCase());simNote.textContent='The RL lab turns learning into a state-value landscape; higher 3D surfaces are states the current policy values more.'}
  function renderSystems(){const p=progress(),shards=params.shards||4,rank=params.rank||8,x=Array.from({length:18},(_,i)=>i+1),curve=x.map(v=>1+p*Math.log2(1+v)*(cfg.conceptType==='fsdp'?shards/4:1+rank/16));if(state.view==='2d')renderPlot([{x,y:curve,mode:'lines+markers',type:'scatter',name:'Training efficiency',line:{color:'#2563eb',width:3}}],{xaxis:{...layout2d.xaxis,title:cfg.conceptType==='fsdp'?'Devices / shards':'Adapter capacity'},yaxis:{...layout2d.yaxis,title:'Relative efficiency / adaptation'}});else{const ys=Array.from({length:16},(_,i)=>i+1),Z=ys.map(y=>x.map(xx=>1+p*Math.log2(1+xx)*(1+.05*y)*(cfg.conceptType==='fsdp'?shards/4:1+rank/20)));render3D([{x,y:ys,z:Z,type:'surface',colorscale:'Blues',showscale:false}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'Parallelism / rank'},yaxis:{...scene3d.yaxis,title:'Batch / model scale'},zaxis:{...scene3d.zaxis,title:'Relative throughput'}}})}practicalMetrics.innerHTML=metric('Relative final efficiency',curve.at(-1).toFixed(2)+'×')+metric(cfg.conceptType==='fsdp'?'Shards':'Adapter rank',shards||rank)+metric('Progress',`${Math.round(p*100)}%`)+metric('View',state.view.toUpperCase());simNote.textContent='Systems/enabler pages use 3D to show training-efficiency response across two scale dimensions rather than a class boundary.'}
  function renderDetection(){const p=progress(),boxes=state.data;if(state.view==='2d'){const shapes=[];boxes.forEach((b,i)=>{const err=(1-p)*(.08*Math.sin(i+state.seed)+.04);shapes.push({type:'rect',x0:b.x-err,y0:b.y+err,x1:b.x+b.w+err,y1:b.y+b.h-err,line:{color:COLORS[i%COLORS.length],width:3}})});renderPlot([{x:[0,1],y:[0,1],mode:'markers',type:'scatter',marker:{opacity:0},showlegend:false}],{xaxis:{...layout2d.xaxis,range:[0,1],title:'Image x'},yaxis:{...layout2d.yaxis,range:[0,1],title:'Image y',scaleanchor:'x'},shapes})}else{const xs=Array.from({length:25},(_,i)=>i/24),ys=[...xs],Z=ys.map(y=>xs.map(x=>boxes.reduce((s,b)=>s+Math.exp(-45*((x-(b.x+b.w/2))**2+(y-(b.y+b.h/2))**2)),0)*p));render3D([{x:xs,y:ys,z:Z,type:'surface',colorscale:'Blues',showscale:false}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'Image x'},yaxis:{...scene3d.yaxis,title:'Image y'},zaxis:{...scene3d.zaxis,title:'Object confidence'}}})}practicalMetrics.innerHTML=metric('Localization maturity',`${Math.round(p*100)}%`)+metric('Objects',boxes.length)+metric('Confidence threshold',pretty(params.confidence||.45))+metric('View',state.view.toUpperCase());simNote.textContent='2D shows bounding-box localization improving; 3D turns objectness/confidence into a surface over image coordinates.'}
  function renderGraph(){const p=progress(),g=state.data,n=g.nodes,depth=Math.max(1,Math.round((params.layers||2)*Math.max(.25,p))),target=3;const adj=Array.from({length:n.length},()=>[]);g.edges.forEach(([a,b])=>{adj[a].push(b);adj[b].push(a)});let frontier=[target],seen=new Set([target]);for(let d=0;d<depth;d++){const next=[];frontier.forEach(v=>adj[v].forEach(u=>{if(!seen.has(u)){seen.add(u);next.push(u)}}));frontier=next}const edgeTrace=(z3=false)=>{const x=[],y=[],z=[];g.edges.forEach(([a,b])=>{x.push(n[a].x,n[b].x,null);y.push(n[a].y,n[b].y,null);if(z3)z.push(n[a].z,n[b].z,null)});return z3?{x,y,z,mode:'lines',type:'scatter3d',name:'Edges',line:{color:document.documentElement.dataset.theme==='dark'?'#475569':'#cbd5e1',width:3}}:{x,y,mode:'lines',type:'scatter',name:'Edges',hoverinfo:'skip',line:{color:document.documentElement.dataset.theme==='dark'?'#475569':'#cbd5e1',width:1.5}}};const col=n.map((q,i)=>i===target?'#f97316':seen.has(i)?'#2563eb':'#94a3b8');if(state.view==='2d')renderPlot([edgeTrace(false),{x:n.map(q=>q.x),y:n.map(q=>q.y),mode:'markers+text',text:n.map(q=>String(q.id)),textposition:'middle center',type:'scatter',name:'Nodes',marker:{size:n.map((q,i)=>i===target?22:16),color:col,line:{color:'#fff',width:1}}}],{xaxis:{...layout2d.xaxis,title:'Graph layout x',showticklabels:false},yaxis:{...layout2d.yaxis,title:'Graph layout y',showticklabels:false}});else render3D([edgeTrace(true),{x:n.map(q=>q.x),y:n.map(q=>q.y),z:n.map((q,i)=>q.z+p*(seen.has(i)?.8:0)),mode:'markers+text',text:n.map(q=>String(q.id)),type:'scatter3d',name:'Node embeddings',marker:{size:n.map((q,i)=>i===target?8:5),color:col}}],{scene:{...scene3d,xaxis:{...scene3d.xaxis,title:'Layout x'},yaxis:{...scene3d.yaxis,title:'Layout y'},zaxis:{...scene3d.zaxis,title:'Learned embedding signal'}}});practicalMetrics.innerHTML=metric('Propagation depth',depth)+metric('Reached nodes',seen.size)+metric('Training progress',`${Math.round(p*100)}%`)+metric('Architecture',cfg.name);simNote.textContent=state.view==='3d'?'3D exposes graph structure plus a learned embedding signal: reached nodes rise as information propagates.':'Highlighted nodes are currently inside the target node’s receptive field.'}
  function renderPractical(){if(cfg.simulationType==='graph')return renderGraph();if(isMulticlass&&cfg.task==='classification')return renderMulticlass();if(cfg.task==='classification')return renderClassification();if(cfg.task==='regression')return renderRegression();if(cfg.simulationType==='clustering')return renderClustering();if(cfg.simulationType==='dimensionality')return renderDimensionality();if(cfg.simulationType==='anomaly')return renderAnomaly();if(cfg.simulationType==='timeseries')return renderTime();if(cfg.simulationType==='representation')return renderRepresentation(false);if(cfg.simulationType==='generative')return renderRepresentation(true);if(cfg.simulationType==='rl')return renderRL();if(cfg.simulationType==='systems')return renderSystems();if(cfg.simulationType==='detection')return renderDetection();return renderRepresentation(false)}
  function rerender(){updateProgress();renderConcept();renderPractical()}
  const copy=document.getElementById('copyCode');if(copy)copy.addEventListener('click',async()=>{const code=document.getElementById('pythonCode').innerText;try{await navigator.clipboard.writeText(code);copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy code',1300)}catch{copy.textContent='Select & copy'}});if(window.hljs)hljs.highlightAll();buildControls();generateData();rerender();window.addEventListener('humach-theme-change',()=>{refreshPlotTheme();rerender()});
